class Board:
    def __init__(self):
        self.board = [[None for _ in range(8)] for _ in range(8)]
        self.initialize_board()

    def initialize_board(self):
        # Initialize the board with pieces
        self.board[0] = [Rook('black'), Knight('black'), Bishop('black'), Queen('black'), King('black'), Bishop('black'), Knight('black'), Rook('black')]
        self.board[1] = [Pawn('black') for _ in range(8)]
        self.board[7] = [Rook('white'), Knight('white'), Bishop('white'), Queen('white'), King('white'), Bishop('white'), Knight('white'), Rook('white')]
        self.board[6] = [Pawn('white') for _ in range(8)]

    def print_board(self):
        for row in self.board:
            print(" ".join([str(piece) if piece else '.' for piece in row]))

    def move_piece(self, start, end):
        # Move a piece from start to end
        start_row, start_col = start
        end_row, end_col = end
        piece = self.board[start_row][start_col]
        if piece and self.is_valid_move(start, end):
            self.board[start_row][start_col] = None
            self.board[end_row][end_col] = piece
            if isinstance(piece, Pawn) and (end_row == 0 or end_row == 7):
                self.board[end_row][end_col] = Queen(piece.color)

    def is_valid_move(self, start, end):
        # Check if the move is valid
        start_row, start_col = start
        end_row, end_col = end
        piece = self.board[start_row][start_col]
        if piece:
            if isinstance(piece, Pawn):
                if piece.color == 'white':
                    if end_row == start_row - 1 and end_col == start_col:
                        return True
                    elif end_row == start_row - 2 and end_col == start_col and start_row == 6:
                        return True
                    elif end_row == start_row - 1 and abs(end_col - start_col) == 1 and self.board[end_row][end_col] is not None:
                        return True
                else:
                    if end_row == start_row + 1 and end_col == start_col:
                        return True
                    elif end_row == start_row + 2 and end_col == start_col and start_row == 1:
                        return True
                    elif end_row == start_row + 1 and abs(end_col - start_col) == 1 and self.board[end_row][end_col] is not None:
                        return True
            elif isinstance(piece, Rook):
                if start_row == end_row or start_col == end_col:
                    return True
            elif isinstance(piece, Knight):
                if abs(end_row - start_row) == 2 and abs(end_col - start_col) == 1 or abs(end_row - start_row) == 1 and abs(end_col - start_col) == 2:
                    return True
            elif isinstance(piece, Bishop):
                if abs(end_row - start_row) == abs(end_col - start_col):
                    return True
            elif isinstance(piece, Queen):
                if start_row == end_row or start_col == end_col or abs(end_row - start_row) == abs(end_col - start_col):
                    return True
            elif isinstance(piece, King):
                if abs(end_row - start_row) <= 1 and abs(end_col - start_col) <= 1:
                    return True
        return False
